package com.portfolio.urlshortener.service;
import org.junit.jupiter.api.Test;import org.springframework.data.redis.core.StringRedisTemplate;import org.springframework.data.redis.core.script.DefaultRedisScript;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.time.Duration;import java.util.List;
class RateLimitServiceTest {@Test void permitsWithinLimit(){StringRedisTemplate r=mock(StringRedisTemplate.class);DefaultRedisScript<Long>s=mock(DefaultRedisScript.class);when(r.execute(eq(s),anyList(),any())).thenReturn(1L,2L,3L);var svc=new RateLimitService(r,s);assertTrue(svc.allow("x",2,Duration.ofMinutes(1)));assertTrue(svc.allow("x",2,Duration.ofMinutes(1)));assertFalse(svc.allow("x",2,Duration.ofMinutes(1)));}@Test void failsOpenWhenRedisUnavailable(){StringRedisTemplate r=mock(StringRedisTemplate.class);DefaultRedisScript<Long>s=mock(DefaultRedisScript.class);when(r.execute(eq(s),anyList(),any())).thenThrow(new RuntimeException());assertTrue(new RateLimitService(r,s).allow("x",1,Duration.ofMinutes(1)));}}
